package com.quest.voiceover.utility;

public class LevenshteinUtility {

    public static int distance(String source, String target) {
        if (source.length() < target.length()) {
            String swap = source;
            source = target;
            target = swap;
        }

        int[] previousRow = new int[target.length() + 1];
        int[] currentRow = new int[target.length() + 1];

        for (int targetIndex = 0; targetIndex <= target.length(); targetIndex++) {
            previousRow[targetIndex] = targetIndex;
        }

        for (int sourceIndex = 1; sourceIndex <= source.length(); sourceIndex++) {
            currentRow[0] = sourceIndex;
            for (int targetIndex = 1; targetIndex <= target.length(); targetIndex++) {
                int cost = source.charAt(sourceIndex - 1) == target.charAt(targetIndex - 1) ? 0 : 1;
                currentRow[targetIndex] = Math.min(
                    Math.min(previousRow[targetIndex] + 1, currentRow[targetIndex - 1] + 1),
                    previousRow[targetIndex - 1] + cost
                );
            }
            int[] swap = previousRow;
            previousRow = currentRow;
            currentRow = swap;
        }

        return previousRow[target.length()];
    }

    public static double similarity(String source, String target) {
        int distance = distance(source, target);
        int maxLength = Math.max(source.length(), target.length());
        return maxLength == 0 ? 1.0 : 1.0 - ((double) distance / maxLength);
    }
}

package com.quest.voiceover.utility;

public final class MessageUtility {

    private MessageUtility() {}

    public static final class ParsedMessage {
        private final String characterName;
        private final String dialogText;
        private final String messageId;

        private ParsedMessage(String characterName, String dialogText, String messageId) {
            this.characterName = characterName;
            this.dialogText = dialogText;
            this.messageId = messageId;
        }

        public String characterName() {
            return characterName;
        }

        public String dialogText() {
            return dialogText;
        }

        public String messageId() {
            return messageId;
        }
    }

    public static ParsedMessage parseRawMessage(String rawMessage, String playerName, String playerVoiceName) {
        String[] parts = rawMessage.split("\\|", 2);

        String characterName = normalizeCharacterName(parts[0], playerName, playerVoiceName);
        String dialogText = parts[1].trim();
        String messageId = HashUtility.toMD5(characterName + "|" + dialogText);

        return new ParsedMessage(characterName, dialogText, messageId);
    }

    public static String cleanWidgetText(String text, String playerName) {
        String cleaned = TextUtility.cleanForMatching(text);

        if (playerName != null && !playerName.isEmpty()) {
            cleaned = cleaned.replace(playerName, "");
        }

        return cleaned;
    }

    private static String normalizeCharacterName(String name, String playerName, String playerVoiceName) {
        return name.equals(playerName) ? playerVoiceName : name;
    }
}

package com.quest.voiceover.utility;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

public final class PluginVersionUtility {

    private static final String VERSION_RESOURCE = "/com/quest/voiceover/version.properties";
    private static final String UNKNOWN_VERSION = "Unknown";

    private static final String VERSION = load();

    private PluginVersionUtility() {}

    public static String get() {
        return VERSION;
    }

    public static boolean isKnown() {
        return !UNKNOWN_VERSION.equals(VERSION);
    }

    private static String load() {
        try (InputStream input = PluginVersionUtility.class.getResourceAsStream(VERSION_RESOURCE)) {
            if (input != null) {
                Properties props = new Properties();
                props.load(input);
                return props.getProperty("version", UNKNOWN_VERSION);
            }
        } catch (IOException ignored) {
        }
        return UNKNOWN_VERSION;
    }
}

package com.quest.voiceover.utility;

public final class TextUtility {

    private static final String OSRS_COLOR_TAG_PATTERN = "<col=[^>]*>";
    private static final String OSRS_COLOR_CLOSE_TAG = "</col>";
    private static final String OSRS_LINE_BREAK = "<br>";

    private TextUtility() {}

    public static String stripColorTags(String text) {
        return text
            .replaceAll(OSRS_COLOR_TAG_PATTERN, "")
            .replace(OSRS_COLOR_CLOSE_TAG, "");
    }

    public static String stripLineBreaks(String text) {
        return text.replace(OSRS_LINE_BREAK, " ");
    }

    public static String stripAllTags(String text) {
        return text.replaceAll("<[^>]+>", "");
    }

    public static String normalizeWhitespace(String text) {
        return text.replaceAll("\\s+", " ").trim();
    }

    public static String cleanForMatching(String text) {
        return normalizeWhitespace(stripAllTags(text));
    }

    public static String reapplyColorAfterLineBreaks(String text, String colorTag) {
        return text.replace(OSRS_LINE_BREAK, OSRS_COLOR_CLOSE_TAG + OSRS_LINE_BREAK + colorTag);
    }
}

package com.quest.voiceover.utility;

import java.awt.Color;

public final class ColorUtility {

    public static final int WHITE = 0xFFFFFF;
    public static final int BLACK = 0x000000;

    private ColorUtility() {}

    public static String toHex(Color color) {
        return String.format("%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
    }

    public static String toOsrsColorTag(Color color) {
        return "<col=" + toHex(color) + ">";
    }

    public static String toOsrsColorTag(String hexColor) {
        return "<col=" + hexColor + ">";
    }

    public static String wrapWithColor(String text, Color color) {
        return toOsrsColorTag(color) + text + "</col>";
    }

    public static String wrapWithColor(String text, String hexColor) {
        return toOsrsColorTag(hexColor) + text + "</col>";
    }
}

package com.quest.voiceover.utility;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public final class HashUtility {

    private HashUtility() {}

    public static String toMD5(String input) {
        return hash(input, "MD5");
    }

    public static String toSHA256(String input) {
        return hash(input, "SHA-256");
    }

    private static String hash(String input, String algorithm) {
        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hash algorithm not available: " + algorithm, e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder(2 * bytes.length);
        for (byte b : bytes) {
            hexString.append(String.format("%02x", b));
        }
        return hexString.toString();
    }
}

package com.quest.voiceover;

import com.google.inject.Provides;
import com.quest.voiceover.features.ChangelogHandler;
import com.quest.voiceover.features.QuestListIndicatorHandler;
import com.quest.voiceover.features.voiceover.overlay.VoiceoverOverlayHandler;
import com.quest.voiceover.features.voiceover.overlay.VoiceoverOverlayMouseListener;
import com.quest.voiceover.features.VoiceoverHandler;
import com.quest.voiceover.modules.audio.AudioDuckingManager;
import com.quest.voiceover.modules.audio.AudioManager;
import com.quest.voiceover.modules.database.DatabaseManager;
import com.quest.voiceover.modules.database.DatabaseVersionManager;
import com.quest.voiceover.modules.dialog.DialogManager;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@PluginDescriptor(name = "Quest Voiceover")
public class QuestVoiceoverPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private DatabaseManager databaseManager;

    @Inject
    private AudioManager audioManager;

    @Inject
    private AudioDuckingManager audioDuckingManager;

    @Inject
    private VoiceoverHandler voiceoverHandler;

    @Inject
    private QuestListIndicatorHandler questListIndicatorHandler;

    @Inject
    private ChangelogHandler changelogHandler;

    @Inject
    private DialogManager dialogManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private VoiceoverOverlayHandler voiceoverOverlay;

    @Inject
    private QuestVoiceoverConfig config;

    private QuestVoiceoverPanel panel;
    private NavigationButton navigationButton;
    private String playerName;
    private VoiceoverOverlayMouseListener voiceoverMouseListener;

    @Override
    protected void startUp() {
        panel = new QuestVoiceoverPanel();
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
        navigationButton = NavigationButton.builder()
            .tooltip("Quest Voiceover")
            .icon(icon)
            .priority(10)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);

        overlayManager.add(voiceoverOverlay);
        voiceoverMouseListener = new VoiceoverOverlayMouseListener(voiceoverOverlay);
        mouseManager.registerMouseListener(voiceoverMouseListener);

        executor.submit(this::initializeDatabase);
        log.info("Quest Voiceover plugin started");
    }

    @Override
    protected void shutDown() throws Exception {
        audioDuckingManager.restore();
        databaseManager.closeConnection();
        clientToolbar.removeNavigation(navigationButton);
        overlayManager.remove(voiceoverOverlay);
        mouseManager.unregisterMouseListener(voiceoverMouseListener);
        log.info("Quest Voiceover plugin stopped");
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.DIALOG) {
            return;
        }

        initializePlayerNameIfNeeded();
        voiceoverHandler.handleDialogMessage(event.getMessage(), playerName);
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (event.getMenuOption().equals("Continue")) {
            voiceoverHandler.stopVoiceover();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (isDialogWidget(event.getGroupId())) {
            voiceoverHandler.handleDialogOpened();
        }

        if (event.getGroupId() == InterfaceID.QUEST_LIST) {
            questListIndicatorHandler.onQuestListOpened();
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event) {
        if (isDialogWidget(event.getGroupId())) {
            voiceoverHandler.stopVoiceover();
        }

        if (event.getGroupId() == InterfaceID.QUEST_LIST) {
            questListIndicatorHandler.onQuestListClosed();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            changelogHandler.checkForUpdate();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        questListIndicatorHandler.onGameTick();

        boolean audioPlaying = audioManager.isPlaying();
        boolean dialogOpen = dialogManager.isPlayerOrNpcDialogOpen();

        if (audioPlaying && !dialogOpen) {
            log.debug("Stopping voiceover - dialog closed");
            audioManager.stopImmediately();
        }
    }

    private boolean isPlayerMoving() {
        var player = client.getLocalPlayer();
        if (player == null) {
            return false;
        }
        int poseAnimation = player.getPoseAnimation();
        int idleAnimation = player.getIdlePoseAnimation();
        return poseAnimation != idleAnimation || client.getLocalDestinationLocation() != null;
    }

    @Provides
    QuestVoiceoverConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(QuestVoiceoverConfig.class);
    }

    private void initializeDatabase() {
        DatabaseVersionManager.prepareDatabaseSource(okHttpClient);
        databaseManager.initializeConnection();
        Set<String> voicedQuests = databaseManager.getVoicedQuests();
        questListIndicatorHandler.setVoicedQuests(voicedQuests);
        SwingUtilities.invokeLater(() -> panel.updateInfo(databaseManager, voicedQuests));
        log.info("Database initialized");
    }

    private void initializePlayerNameIfNeeded() {
        if (playerName == null) {
            playerName = client.getLocalPlayer().getName();
        }
    }

    private boolean isDialogWidget(int groupId) {
        return groupId == InterfaceID.DIALOG_NPC
            || groupId == InterfaceID.DIALOG_PLAYER
            || groupId == InterfaceID.DIALOG_OPTION;
    }
}

package com.quest.voiceover.features.voiceover.overlay;

import net.runelite.client.input.MouseListener;

import java.awt.event.MouseEvent;

public class VoiceoverOverlayMouseListener implements MouseListener {

    private final VoiceoverOverlayHandler overlay;

    public VoiceoverOverlayMouseListener(VoiceoverOverlayHandler overlay) {
        this.overlay = overlay;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent mouseEvent) {
        return mouseEvent;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent mouseEvent) {
        if (overlay.handleClick(mouseEvent.getX(), mouseEvent.getY())) {
            mouseEvent.consume();
        }
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent mouseEvent) {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent mouseEvent) {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent mouseEvent) {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent mouseEvent) {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent mouseEvent) {
        return mouseEvent;
    }
}

package com.quest.voiceover.features.voiceover.overlay.controls;

import com.quest.voiceover.Constants;
import com.quest.voiceover.QuestVoiceoverConfig;
import com.quest.voiceover.features.voiceover.overlay.OverlayControl;
import com.quest.voiceover.modules.audio.AudioManager;
import net.runelite.api.SpriteID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.SpriteManager;

import java.awt.*;
import java.awt.image.BufferedImage;

public class MuteControl implements OverlayControl {

    private static final int ICON_SIZE = 20;

    private final QuestVoiceoverConfig config;
    private final ConfigManager configManager;
    private final AudioManager audioManager;
    private final SpriteManager spriteManager;

    private Rectangle bounds;

    public MuteControl(
            QuestVoiceoverConfig config,
            ConfigManager configManager,
            AudioManager audioManager,
            SpriteManager spriteManager
    ) {
        this.config = config;
        this.configManager = configManager;
        this.audioManager = audioManager;
        this.spriteManager = spriteManager;
    }

    @Override
    public void render(Graphics2D graphics, int x, int y, Point overlayOrigin) {
        BufferedImage icon = getMuteIcon();
        if (icon != null) {
            graphics.drawImage(icon, x, y, ICON_SIZE, ICON_SIZE, null);
        }
        bounds = new Rectangle(overlayOrigin.x + x, overlayOrigin.y + y, ICON_SIZE, ICON_SIZE);
    }

    @Override
    public boolean handleClick(int x, int y) {
        if (bounds == null || !bounds.contains(x, y)) {
            return false;
        }

        configManager.setConfiguration(Constants.PLUGIN_CONFIG_GROUP, "mute", !config.mute());
        audioManager.setVolume(config.mute() ? 0 : config.volume());
        return true;
    }

    @Override
    public int getWidth() {
        return ICON_SIZE;
    }

    private BufferedImage getMuteIcon() {
        int spriteId = config.mute() ? SpriteID.OPTIONS_MUSIC_DISABLED : SpriteID.OPTIONS_MUSIC_VOLUME;
        return spriteManager.getSprite(spriteId, 0);
    }
}

package com.quest.voiceover.features.voiceover.overlay.controls;

import com.quest.voiceover.features.voiceover.overlay.OverlayControl;
import com.quest.voiceover.modules.audio.AudioManager;
import com.quest.voiceover.modules.audio.AudioQueueManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

import java.awt.*;
import java.awt.image.BufferedImage;

public class SkipControl implements OverlayControl {

    private static final int ICON_SIZE = 20;

    private final AudioManager audioManager;
    private final AudioQueueManager audioQueueManager;
    private final BufferedImage nextIcon;

    private Rectangle bounds;

    public SkipControl(AudioManager audioManager, AudioQueueManager audioQueueManager) {
        this.audioManager = audioManager;
        this.audioQueueManager = audioQueueManager;
        this.nextIcon = ImageUtil.loadImageResource(getClass(), "/com/quest/voiceover/player/next.png");
    }

    @Override
    public void render(Graphics2D graphics, int x, int y, Point overlayOrigin) {
        graphics.drawImage(nextIcon, x, y, ICON_SIZE, ICON_SIZE, null);
        bounds = new Rectangle(overlayOrigin.x + x, overlayOrigin.y + y, ICON_SIZE, ICON_SIZE);

        renderQueueCount(graphics, x, y);
    }

    @Override
    public boolean handleClick(int x, int y) {
        if (bounds == null || !bounds.contains(x, y)) {
            return false;
        }

        audioManager.skipToNext();
        return true;
    }

    @Override
    public int getWidth() {
        return ICON_SIZE;
    }

    public boolean hasQueue() {
        return !audioQueueManager.isEmpty();
    }

    private void renderQueueCount(Graphics2D graphics, int buttonX, int buttonY) {
        int queueSize = audioQueueManager.size();
        String queueText = String.valueOf(queueSize);

        graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(11f));
        graphics.setColor(Color.WHITE);
        graphics.drawString(queueText, buttonX + ICON_SIZE - 4, buttonY + 2);
    }
}

package com.quest.voiceover.features.voiceover.overlay.controls;

import com.quest.voiceover.features.voiceover.overlay.OverlayControl;
import com.quest.voiceover.modules.audio.AudioManager;
import net.runelite.client.util.ImageUtil;

import java.awt.*;
import java.awt.image.BufferedImage;

public class PlayPauseControl implements OverlayControl {

    private static final int ICON_SIZE = 20;

    private final AudioManager audioManager;
    private final BufferedImage playIcon;
    private final BufferedImage pauseIcon;

    private Rectangle bounds;

    public PlayPauseControl(AudioManager audioManager) {
        this.audioManager = audioManager;
        this.playIcon = ImageUtil.loadImageResource(getClass(), "/com/quest/voiceover/player/play.png");
        this.pauseIcon = ImageUtil.loadImageResource(getClass(), "/com/quest/voiceover/player/pause.png");
    }

    @Override
    public void render(Graphics2D graphics, int x, int y, Point overlayOrigin) {
        BufferedImage icon = audioManager.isPaused() ? playIcon : pauseIcon;
        graphics.drawImage(icon, x, y, ICON_SIZE, ICON_SIZE, null);
        bounds = new Rectangle(overlayOrigin.x + x, overlayOrigin.y + y, ICON_SIZE, ICON_SIZE);
    }

    @Override
    public boolean handleClick(int x, int y) {
        if (bounds == null || !bounds.contains(x, y)) {
            return false;
        }

        if (audioManager.isPaused()) {
            audioManager.resume();
        } else {
            audioManager.pause();
        }
        return true;
    }

    @Override
    public int getWidth() {
        return ICON_SIZE;
    }
}

