    public void updateInfo(DatabaseManager databaseManager, Set<String> voicedQuests)
    {
        String dbVersion = DatabaseVersionManager.getDatabaseVersion();
        databaseVersionLabel.setText(htmlLabel("Version: ", dbVersion));

        boolean connected = databaseManager.isConnected();
        String statusText = connected ? "Connected" : "Disconnected";
        connectionStatusLabel.setText(htmlLabel("Status: ", statusText));

        int totalQuests = Quest.values().length;
        int voicedCount = voicedQuests != null ? voicedQuests.size() : 0;
        String coverageText = voicedCount + " / " + totalQuests;
        questCoverageLabel.setText(htmlLabel("Quests voiced: ", coverageText));

        double percentage = (voicedCount * 100.0) / totalQuests;
        String percentageText = String.format("%.1f%%", percentage);
        questPercentageLabel.setText(htmlLabel("Completion: ", percentageText));
    }

    private static String htmlLabel(String key, String value)
    {
        return "<html><body>" + key + "<span style='color:white'>" + value + "</span></body></html>";
    }

    /**
     * Drawn at runtime rather than shipped as an asset so the donation button needs no
     * bundled image and carries no third-party logo/trademark.
     */
    private static ImageIcon createHeartIcon()
    {
        BufferedImage image = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(KOFI_RED);

        double lobeDiameter = HEART_LOBE_RADIUS * 2;
        graphics.fill(new Ellipse2D.Double(
            HEART_LEFT_LOBE_CENTER_X - HEART_LOBE_RADIUS, HEART_LOBE_CENTER_Y - HEART_LOBE_RADIUS,
            lobeDiameter, lobeDiameter));
        graphics.fill(new Ellipse2D.Double(
            HEART_RIGHT_LOBE_CENTER_X - HEART_LOBE_RADIUS, HEART_LOBE_CENTER_Y - HEART_LOBE_RADIUS,
            lobeDiameter, lobeDiameter));

        Path2D.Double body = new Path2D.Double();
        body.moveTo(HEART_BODY_TOP_LEFT_X, HEART_BODY_TOP_Y);
        body.lineTo(HEART_BODY_TOP_RIGHT_X, HEART_BODY_TOP_Y);
        body.lineTo(HEART_BODY_TIP_X, HEART_BODY_TIP_Y);
        body.closePath();
        graphics.fill(body);

        graphics.dispose();
        return new ImageIcon(image);
    }

    private static JPanel buildLinkPanel(ImageIcon icon, String topText, String bottomText, String url)
    {
        JPanel container = new JPanel(new BorderLayout());
        container.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        container.setBorder(new EmptyBorder(8, 10, 8, 10));
        container.setCursor(new Cursor(Cursor.HAND_CURSOR));
        container.setAlignmentX(Component.LEFT_ALIGNMENT);
        container.setMaximumSize(new Dimension(Integer.MAX_VALUE, 50));

        JLabel iconLabel = new JLabel(icon);

        JPanel textPanel = new JPanel();
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        textPanel.setBorder(new EmptyBorder(0, 10, 0, 0));

        JLabel topLabel = new JLabel(topText);
        topLabel.setForeground(Color.WHITE);
        topLabel.setFont(FontManager.getRunescapeSmallFont());

        JLabel bottomLabel = new JLabel(bottomText);
        bottomLabel.setForeground(Color.WHITE);
        bottomLabel.setFont(FontManager.getRunescapeSmallFont());

        textPanel.add(topLabel);
        textPanel.add(bottomLabel);

        JLabel arrowLabel = new JLabel(ARROW_RIGHT_ICON);

        container.add(iconLabel, BorderLayout.WEST);
        container.add(textPanel, BorderLayout.CENTER);
        container.add(arrowLabel, BorderLayout.EAST);

        container.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e)
            {
                LinkBrowser.browse(url);
            }

            @Override
            public void mouseEntered(java.awt.event.MouseEvent e)
            {
                container.setBackground(ColorScheme.DARK_GRAY_COLOR);
                textPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
            }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e)
            {
                container.setBackground(ColorScheme.DARKER_GRAY_COLOR);
                textPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            }
        });

        return container;
    }
}

package com.quest.voiceover;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.client.config.*;

@ConfigGroup("quest.voiceover")
public interface QuestVoiceoverConfig extends Config
{
	@RequiredArgsConstructor
	enum PlayerVoice
	{
		AUTO_DETECT(null),
		MALE("Player Male"),
		FEMALE("Player Female");

		private final String characterName;

		public String getCharacterName(Client client)
		{
			if (characterName != null)
			{
				return characterName;
			}

			Player player = client.getLocalPlayer();
			if (player == null)
			{
				return MALE.characterName;
			}

			PlayerComposition composition = player.getPlayerComposition();
			if (composition == null)
			{
				return MALE.characterName;
			}

			return composition.getGender() == 1 ? FEMALE.characterName : MALE.characterName;
		}

		@Override
		public String toString()
		{
			if (this == AUTO_DETECT)
			{
				return "Auto-detect";
			}
			return name().charAt(0) + name().substring(1).toLowerCase();
		}
	}

	@ConfigSection(
			name = "Voice",
			description = "Voice configuration options",
			position = 10,
			closedByDefault = false
	)
	String voiceSettings = "voiceSettings";

	@ConfigItem(
			keyName = "voicePlayerDialog",
			name = "Voice Player Dialog",
			description = "Plays voiceovers for your own character's lines. Disable to hear only NPC voices.",
			section = voiceSettings,
			position = 5
	)
	default boolean voicePlayerDialog()
	{
		return true;
	}

	@ConfigItem(
			keyName = "playerVoice",
			name = "Player Voice",
			description = "Voice used for your character's dialog.",
			section = voiceSettings,
			position = 6
	)
	default PlayerVoice playerVoice()
	{
		return PlayerVoice.AUTO_DETECT;
	}

	@ConfigSection(
			name = "Audio",
			description = "Audio playback settings",
			position = 5,
			closedByDefault = false
	)
	String audioSettings = "audioSettings";

	@ConfigSection(
			name = "Speech Highlighting",
			description = "Settings for speech highlighting",
			position = 20,
			closedByDefault = false
	)
	String speechHighlightingSettings = "speechHighlightingSettings";

	@ConfigSection(
			name = "Display",
			description = "Visual display settings",
			position = 30,
			closedByDefault = false
	)
	String displaySettings = "displaySettings";

	@Range(min = 1, max = 100)
	@ConfigItem(
			keyName = "volume",
			name = "Volume",
			description = "Volume control for the voiceover sounds.",
			position = 11,
			section = audioSettings
	)
	default int volume() {
		return 75;
	}

	@ConfigItem(
			keyName = "mute",
			name = "Mute",
			description = "Mutes the voiceover sound.",
			section = audioSettings,
			position = 12
	)
	default boolean mute()
	{
		return false;
	}

	@ConfigItem(
			keyName = "audioDucking",
			name = "Audio Ducking",
			description = "Lowers game audio while voiceover plays.",
			section = audioSettings,
			position = 13
	)
	default boolean audioDucking()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
			keyName = "audioDuckingAmount",
			name = "Ducking Amount",
			description = "How much to lower game audio (0 = mute, 100 = no change).",
			section = audioSettings,
			position = 14
	)
	default int audioDuckingAmount()
	{
		return 25;
	}

	@ConfigItem(
			keyName = "audioQueuing",
			name = "Audio Queuing",
			description = "Queue voiceovers instead of interrupting. Unfinished lines continue playing when advancing dialog.",
			section = audioSettings,
			position = 15
	)
	default boolean audioQueuing()
	{
		return true;
	}

	@ConfigItem(
			keyName = "finishLastLine",
			name = "Finish Last Line on Exit",
			description = "Interrupt earlier lines when advancing dialog, but let the final line finish playing after you leave the NPC. Overrides Audio Queuing.",
			section = audioSettings,
			position = 16
	)
	default boolean finishLastLine()
	{
		return false;
	}

	@ConfigItem(
			keyName = "speechHighlighting",
			name = "Speech Highlighting",
			description = "Highlights dialog text word-by-word as it is spoken.",
			section = speechHighlightingSettings,
			position = 21
	)
	default boolean speechHighlighting()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
			keyName = "speechHighlightColor",
			name = "Speech Highlight Color",
			description = "Color used to highlight words that have been spoken.",
			section = speechHighlightingSettings,
			position = 22
	)
	default java.awt.Color speechHighlightColor()
	{
		return new java.awt.Color(0xFF0054BA, true);
	}

	@ConfigItem(
			keyName = "showVoiceoverOverlay",
			name = "Show Voiceover Overlay",
			description = "Shows an overlay with playback controls when voiceover is playing.",
			section = displaySettings,
			position = 31
	)
	default boolean showVoiceoverOverlay()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showVoicedIndicator",
			name = "Show Voiced Quest Indicator",
			description = "Shows [Voiced] prefix next to quests with voice acting in the quest list.",
			section = displaySettings,
			position = 32
	)
	default boolean showVoicedIndicator()
	{
		return true;
	}
}

